def clip(poly, inside, cut):
    out = []
    for i in range(len(poly)):
        p = poly[i-1]
        q = poly[i]
        ip, iq = inside(p), inside(q)
        if ip and iq:
            out.append(q)
        elif ip and not iq:
            out.append(cut(p, q))
        elif not ip and iq:
            out.append(cut(p, q))
            out.append(q)
    return out

def cut_at_x(k):
    def cut(a, b):
        t = (k - a[0]) / (b[0] - a[0])
        return (k, a[1] + t * (b[1] - a[1]))
    return cut

def cut_at_y(k):
    def cut(a, b):
        t = (k - a[1]) / (b[1] - a[1])
        return (a[0] + t * (b[0] - a[0]), k)
    return cut

poly = [(0, 0), (4, 0), (4, 4), (0, 4)]
poly = clip(poly, lambda p: p[0] >= 1, cut_at_x(1))
poly = clip(poly, lambda p: p[0] <= 3, cut_at_x(3))
poly = clip(poly, lambda p: p[1] >= 1, cut_at_y(1))
poly = clip(poly, lambda p: p[1] <= 3, cut_at_y(3))
start = min(range(len(poly)), key=lambda i: poly[i])
poly = poly[start:] + poly[:start]
for x, y in poly:
    print(int(x))
    print(int(y))
